-- Metric cases for the triage testsets (metrics.baml). Apply in the Supabase
-- dashboard (eval/ is gitignored, so this copy is the one that ships); eval/cases.json
-- is the same data for local runs (ATB2_CASES_FILE).
create table if not exists triage_cases (
  id      text primary key,
  metric  text not null check (metric in ('kind', 'dedup', 'fixed')),
  payload jsonb not null,
  source  text
);
alter table triage_cases enable row level security;
drop policy if exists "eval read" on triage_cases;
create policy "eval read" on triage_cases for select to anon using (true);
begin;
delete from triage_cases;
commit;
